<div class="section-head"><div><span class="eyebrow"><?=e($contest['lifecycle_status'])?></span><h2><?=e($contest['contest_title'])?> problems</h2><p class="muted">Choose a problem and submit your solution during the contest.</p></div><?php if(has_role('ORGANIZER')&&(int)$contest['organizer_user_id']===(int)user()['user_id']):?><a class="button" href="<?=e(url('/organizer/contests/'.$contest['contest_id'].'/problems/create'))?>">+ Add problem</a><?php endif;?></div>
<div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Title</th><th>Difficulty</th><th>Time</th><th>Memory</th><th>Action</th></tr></thead><tbody><?php foreach($problems as $p):?><tr><td><strong><?=e($p['problem_code'])?></strong></td><td><?=e($p['problem_title'])?></td><td><?=e($p['difficulty'])?></td><td><?=e($p['time_limit_ms'])?> ms</td><td><?=e($p['memory_limit_mb'])?> MB</td><td class="actions"><a href="<?=e(url('/problems/'.$p['problem_id']))?>">Open</a><?php if(has_role('ORGANIZER')&&(int)$contest['organizer_user_id']===(int)user()['user_id']):?><a href="<?=e(url('/organizer/contests/'.$contest['contest_id'].'/problems/'.$p['problem_id'].'/edit'))?>">Edit</a><a href="<?=e(url('/organizer/problems/'.$p['problem_id'].'/tests'))?>">Tests</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$problems):?><tr><td colspan="6" class="empty">No published problems.</td></tr><?php endif;?></tbody></table></div>
